&lt;div&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:georgia,serif"&gt;&lt;strong&gt;December 10, 2025&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:georgia,serif"&gt;FOR IMMEDIATE RELEASE&lt;/span&gt;&lt;/span&gt;&lt;br /&gt;
