&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;Feb. 3:&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;Manager Essentials &mdash; building trust, setting&amp;nbsp;expectations&amp;nbsp;and coaching performance&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
